// One trace per unique subject. Repeat CSV rows are dropped here, not paid for.
function clean(value) {
  return String(value === null || value === undefined ? '' : value).trim();
}

const seen = {};
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const row = Object.assign({}, j);

  const key = [
    clean(j.req_SSN), clean(j.req_FNAME), clean(j.req_MNAME), clean(j.req_LNAME),
    clean(j.req_ADDRESS), clean(j.req_CITY), clean(j.req_STATE),
  ].join('|').toUpperCase();

  if (seen[key] && key !== '||||||') continue;
  seen[key] = true;

  row.subject_id = String(out.length + 1);
  row.searched_name = [clean(j.req_FNAME), clean(j.req_MNAME), clean(j.req_LNAME)]
    .filter(Boolean).join(' ');
  row.searched_city = clean(j.req_CITY);
  row.searched_state = clean(j.req_STATE);

  out.push({ json: row, pairedItem: { item: i } });
}

return out;

// api_trace answers with [{ Status, Data: { response: { status, transaction-id,
// subject-count, record } }, Error }] — record is a bare object when there is one
// address and an array when there are several.
function s(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return '';
  return String(value).trim();
}

function toArr(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

function pad(value) {
  const v = s(value);
  return v.length === 1 ? '0' + v : v;
}

function last4(value) {
  const digits = s(value).replace(/[^0-9]/g, '');
  return digits.length >= 4 ? digits.slice(-4) : '';
}

function fmtDate(o, withDay) {
  if (!o || typeof o !== 'object') return '';
  const y = s(o.year), m = s(o.month), d = s(o.day);
  if (withDay) return (y && m && d) ? (y + '-' + pad(m) + '-' + pad(d)) : '';
  return (y && m) ? (y + '-' + pad(m)) : '';
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const ctx = items[i].json;
  const raw = ctx.response;

  const blank = {
    SUBJECT_ID: s(ctx.subject_id),
    SEARCHED_NAME: s(ctx.searched_name),
    SEARCHED_CITY: s(ctx.searched_city),
    SEARCHED_STATE: s(ctx.searched_state),
    input_row_id: s(ctx.input_row_id),
    search_type: s(ctx.search_type),
    api_status: '', subject_count: '', transaction_id: '', result_number: '',
    type: '', first_name: '', middle_name: '', last_name: '', full_name: '',
    address: '', unit: '', city: '', state: '', zip: '', zip4: '', county: '',
    phone: '', dob: '', age: '', date_first: '', date_last: '', ssn_last4: '',
    raw_status: '', error_message: '',
  };

  // network or HTTP failure (the API node continues on error)
  if (raw && raw.error !== undefined && raw.error !== null && raw.Data === undefined && !Array.isArray(raw)) {
    const message = (raw.error && raw.error.message) ? raw.error.message : raw.error;
    out.push({ json: Object.assign({}, blank, { api_status: 'ERROR', error_message: s(message) }), pairedItem: { item: i } });
    continue;
  }

  const root = Array.isArray(raw) ? (raw[0] || {}) : (raw || {});
  const data = root.Data || {};
  const response = data.response || {};
  const rawStatus = s(root.Status) || s(response.status);
  const txn = s(response['transaction-id']);
  const records = toArr(response.record);
  const subjectCount = s(response['subject-count']) || String(records.length);
  const apiError = (root.Error !== undefined && root.Error !== null && root.Error !== '') ? root.Error : '';

  if (apiError) {
    out.push({ json: Object.assign({}, blank, {
      api_status: 'ERROR', raw_status: rawStatus, transaction_id: txn,
      error_message: typeof apiError === 'object' ? JSON.stringify(apiError) : s(apiError),
    }), pairedItem: { item: i } });
    continue;
  }

  if (records.length === 0) {
    out.push({ json: Object.assign({}, blank, {
      api_status: 'NORESULTS', raw_status: rawStatus,
      subject_count: subjectCount, transaction_id: txn,
    }), pairedItem: { item: i } });
    continue;
  }

  for (let r = 0; r < records.length; r++) {
    const rec = records[r];
    const fn = s(rec['name-first']);
    const mn = s(rec['name-middle']);
    const ln = s(rec['name-last']);
    const address = [rec['street-number'], rec['street-pre-direction'], rec['street-name'],
      rec['street-post-direction'], rec['street-suffix']].map(s).filter(Boolean).join(' ');
    const unit = [rec['unit-designation'], rec['unit-number']].map(s).filter(Boolean).join(' ');
    const phone = Object.keys(rec).filter((k) => /^phone/i.test(k))
      .map((k) => s(rec[k])).filter(Boolean).join(' | ');

    out.push({
      json: Object.assign({}, blank, {
        api_status: 'SUCCESS',
        subject_count: subjectCount,
        transaction_id: txn,
        result_number: String(r + 1),
        type: s(rec['type']),
        first_name: fn, middle_name: mn, last_name: ln,
        full_name: [fn, mn, ln].filter(Boolean).join(' '),
        address: address, unit: unit,
        city: s(rec['city']), state: s(rec['state']),
        zip: s(rec['zip']), zip4: s(rec['zip4']), county: s(rec['county']),
        phone: phone,
        dob: fmtDate(rec['dob'], true),
        age: s(rec['age']),
        date_first: fmtDate(rec['date-first'], false),
        date_last: fmtDate(rec['date-last'], false),
        ssn_last4: last4(rec['ssn']),
        raw_status: rawStatus,
      }),
      pairedItem: { item: i },
    });
  }
}

return out;

// Turns a bag of addresses into a relocation timeline: what order the person
// lived at them, how long each one lasted, and which one is current.
function monthIndex(value) {
  const v = String(value === null || value === undefined ? '' : value).trim();
  const m = v.match(/^(\d{4})-(\d{2})/);
  if (!m) return null;
  return Number(m[1]) * 12 + (Number(m[2]) - 1);
}

function norm(value) {
  return String(value === null || value === undefined ? '' : value)
    .toUpperCase().replace(/[^A-Z ]/g, ' ').replace(/\s+/g, ' ').trim();
}

function part(searched, found) {
  if (!searched || !found) return 0;
  if (searched === found) return 1;
  if (found.startsWith(searched) || searched.startsWith(found)) return 0.5;
  return 0;
}

function round(value, places) {
  const f = Math.pow(10, places);
  return Math.round(value * f) / f;
}

const now = new Date();
const nowIndex = now.getUTCFullYear() * 12 + now.getUTCMonth();

// group by subject so the timeline is built per person
const groups = {};
const order = [];
for (const item of $input.all()) {
  const key = String(item.json.SUBJECT_ID || '');
  if (!groups[key]) { groups[key] = []; order.push(key); }
  groups[key].push(item.json);
}

const out = [];

for (const key of order) {
  const rows = groups[key];

  const usable = rows.filter((r) => r.api_status === 'SUCCESS');
  if (usable.length === 0) {
    for (const row of rows) {
      const copy = Object.assign({}, row);
      copy.NAME_MATCH_SCORE = 0;
      copy.MOVE_SEQUENCE = 0;
      copy.IS_CURRENT = 'No';
      copy.MONTHS_AT_ADDRESS = '';
      copy.YEARS_SINCE_LAST_SEEN = '';
      copy.MOVED_STATE = '';
      copy.FLAGS = row.api_status === 'ERROR' ? 'API_ERROR' : 'NO_TRACE_RESULTS';
      out.push({ json: copy });
    }
    continue;
  }

  // oldest first; rows with no dates keep their original order at the end
  const sorted = usable.slice().sort((a, b) => {
    const av = monthIndex(a.date_first);
    const bv = monthIndex(b.date_first);
    if (av === null && bv === null) return 0;
    if (av === null) return 1;
    if (bv === null) return -1;
    return av - bv;
  });

  // the current address is the one seen most recently
  let currentRow = null;
  let currentSeen = -Infinity;
  for (const row of sorted) {
    const seen = monthIndex(row.date_last);
    if (seen !== null && seen > currentSeen) { currentSeen = seen; currentRow = row; }
  }
  if (!currentRow) currentRow = sorted[sorted.length - 1];

  let previousState = '';
  for (let i = 0; i < sorted.length; i++) {
    const row = Object.assign({}, sorted[i]);

    const searched = norm(row.SEARCHED_NAME).split(' ').filter(Boolean);
    let score = 0;
    if (searched.length > 0) {
      const searchedFirst = searched[0];
      const searchedLast = searched.length > 1 ? searched[searched.length - 1] : '';
      score += 40 * part(searchedFirst, norm(row.first_name));
      score += 60 * part(searchedLast, norm(row.last_name));
    } else {
      score = 100; // traced by SSN or address, so there was no name to match
    }
    row.NAME_MATCH_SCORE = Math.round(score);

    row.MOVE_SEQUENCE = i + 1;
    row.IS_CURRENT = sorted[i] === currentRow ? 'Yes' : 'No';

    const first = monthIndex(row.date_first);
    const last = monthIndex(row.date_last);
    row.MONTHS_AT_ADDRESS = (first !== null && last !== null && last >= first) ? (last - first) : '';
    row.YEARS_SINCE_LAST_SEEN = last !== null ? round((nowIndex - last) / 12, 1) : '';

    const state = String(row.state || '').toUpperCase();
    row.MOVED_STATE = i === 0 ? 'N/A' : (state && previousState && state !== previousState ? 'Yes' : 'No');

    const flags = [];
    if (row.IS_CURRENT === 'Yes') flags.push('CURRENT_ADDRESS');
    if (row.MOVED_STATE === 'Yes') flags.push('OUT_OF_STATE_MOVE');
    if (row.MONTHS_AT_ADDRESS !== '' && row.MONTHS_AT_ADDRESS < 12) flags.push('SHORT_STAY');
    if (row.MONTHS_AT_ADDRESS !== '' && row.MONTHS_AT_ADDRESS >= 60) flags.push('LONG_TERM');
    if (row.YEARS_SINCE_LAST_SEEN !== '' && row.YEARS_SINCE_LAST_SEEN <= 2 && row.IS_CURRENT === 'Yes') flags.push('RECENT_MOVE');
    if (first === null && last === null) flags.push('NO_DATES');
    if (row.NAME_MATCH_SCORE < 60) flags.push('WEAK_NAME_MATCH');
    row.FLAGS = flags.join(', ');

    if (state) previousState = state;
    out.push({ json: row });
  }
}

return out;

// One row per person traced: where they are now, where they have been, and how
// often they move.
function round(value, places) {
  const f = Math.pow(10, places);
  return Math.round(value * f) / f;
}

function monthIndex(value) {
  const v = String(value === null || value === undefined ? '' : value).trim();
  const m = v.match(/^(\d{4})-(\d{2})/);
  if (!m) return null;
  return Number(m[1]) * 12 + (Number(m[2]) - 1);
}

const groups = {};
const order = [];

for (const item of $input.all()) {
  const j = item.json;
  const key = String(j.SUBJECT_ID || '');

  if (!groups[key]) {
    order.push(key);
    groups[key] = {
      SUBJECT_ID: key,
      INPUT_ROW_ID: j.input_row_id || '',
      SEARCH_TYPE: j.search_type || '',
      SEARCHED_NAME: j.SEARCHED_NAME || '',
      API_STATUS: j.api_status || '',
      ADDRESSES_FOUND: 0,
      STATES: {},
      PHONES: {},
      CURRENT_ADDRESS: '', CURRENT_CITY: '', CURRENT_STATE: '', CURRENT_SINCE: '',
      EARLIEST_SEEN: '',
      LATEST_SEEN: '',
      OUT_OF_STATE_MOVES: 0,
      MONTHS_TOTAL: 0,
      MONTHS_COUNT: 0,
      BEST_NAME_MATCH: 0,
    };
  }

  const g = groups[key];
  if (j.api_status !== 'SUCCESS') continue;

  g.API_STATUS = 'SUCCESS';
  g.ADDRESSES_FOUND++;
  if (j.state) g.STATES[String(j.state).toUpperCase()] = true;
  String(j.phone || '').split('|').map((p) => p.trim()).filter(Boolean)
    .forEach((p) => { g.PHONES[p] = true; });

  if (j.MOVED_STATE === 'Yes') g.OUT_OF_STATE_MOVES++;
  if (Number(j.NAME_MATCH_SCORE) > g.BEST_NAME_MATCH) g.BEST_NAME_MATCH = Number(j.NAME_MATCH_SCORE);
  if (j.MONTHS_AT_ADDRESS !== '' && j.MONTHS_AT_ADDRESS !== null && j.MONTHS_AT_ADDRESS !== undefined) {
    g.MONTHS_TOTAL += Number(j.MONTHS_AT_ADDRESS) || 0;
    g.MONTHS_COUNT++;
  }

  if (j.IS_CURRENT === 'Yes') {
    g.CURRENT_ADDRESS = [j.address, j.unit].filter(Boolean).join(' ');
    g.CURRENT_CITY = j.city || '';
    g.CURRENT_STATE = j.state || '';
    g.CURRENT_SINCE = j.date_first || '';
  }

  const first = monthIndex(j.date_first);
  const last = monthIndex(j.date_last);
  if (first !== null) {
    const existing = monthIndex(g.EARLIEST_SEEN);
    if (existing === null || first < existing) g.EARLIEST_SEEN = j.date_first;
  }
  if (last !== null) {
    const existing = monthIndex(g.LATEST_SEEN);
    if (existing === null || last > existing) g.LATEST_SEEN = j.date_last;
  }
}

const summaryDate = new Date().toISOString().slice(0, 10);

return order.map((key) => {
  const g = groups[key];
  const moves = g.ADDRESSES_FOUND > 0 ? g.ADDRESSES_FOUND - 1 : 0;
  const earliest = monthIndex(g.EARLIEST_SEEN);
  const latest = monthIndex(g.LATEST_SEEN);
  const yearsTraced = (earliest !== null && latest !== null && latest >= earliest)
    ? round((latest - earliest) / 12, 1) : '';
  const avgMonths = g.MONTHS_COUNT > 0 ? round(g.MONTHS_TOTAL / g.MONTHS_COUNT, 1) : '';

  // one address on file says nothing about how often someone moves
  let mobility = 'UNKNOWN';
  if (avgMonths !== '' && g.ADDRESSES_FOUND >= 2) {
    if (avgMonths < 24) mobility = 'HIGH';
    else if (avgMonths < 60) mobility = 'MEDIUM';
    else mobility = 'LOW';
  }

  return {
    json: {
      SUBJECT_ID: g.SUBJECT_ID,
      INPUT_ROW_ID: g.INPUT_ROW_ID,
      SEARCH_TYPE: g.SEARCH_TYPE,
      SEARCHED_NAME: g.SEARCHED_NAME,
      API_STATUS: g.API_STATUS,
      ADDRESSES_FOUND: g.ADDRESSES_FOUND,
      STATES_LIVED: Object.keys(g.STATES).sort().join(', '),
      CURRENT_ADDRESS: g.CURRENT_ADDRESS,
      CURRENT_CITY: g.CURRENT_CITY,
      CURRENT_STATE: g.CURRENT_STATE,
      CURRENT_SINCE: g.CURRENT_SINCE,
      EARLIEST_SEEN: g.EARLIEST_SEEN,
      YEARS_TRACED: yearsTraced,
      MOVES_COUNT: moves,
      OUT_OF_STATE_MOVES: g.OUT_OF_STATE_MOVES,
      AVG_MONTHS_PER_ADDRESS: avgMonths,
      MOBILITY_TIER: mobility,
      BEST_NAME_MATCH: g.BEST_NAME_MATCH,
      PHONES_ALL: Object.keys(g.PHONES).join(' | '),
      SUMMARY_DATE: summaryDate,
    },
  };
});
